package io.github.diodeme.ji.session.jsonl;

import io.github.diodeme.ji.session.tck.SessionRepositoryTck;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

final class JsonlSessionRepositoryTckTest extends SessionRepositoryTck {
    private final Path root;

    JsonlSessionRepositoryTckTest() throws IOException {
        root = Files.createTempDirectory("ji-jsonl-tck-");
    }

    @Override
    protected SessionRepository createRepository() {
        return new JsonlSessionRepository(root.resolve(java.util.UUID.randomUUID().toString()));
    }
}
